with temp as (select m.title as results from movierating as mr join movies as m on m.movie_id=mr.movie_id  where mr.created_at between '2020-02-01' and '2020-02-29' group by m.movie_id order by avg(mr.rating) desc , m.title asc limit 1),
temp1 as (select u.name from movierating as mr join users as u on u.user_id=mr.user_id group by u.user_id order by count(u.user_id) desc , u.name asc limit 1)
select * from temp union all select * from temp1